/* From Uiverse.io by KSAplay - Tags: checkbox, like, heart */
.__UIV_SCOPE__ .container input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
  transition: 100ms;
}

.__UIV_SCOPE__ .checkmark {
  top: 0;
  left: 0;
  height: 2em;
  width: 2em;
  transition: 100ms;
  animation: dislike_effect 400ms ease;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark path {
  fill: #FF5353;
  stroke-width: 0;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  animation: like_effect 400ms ease;
}

.__UIV_SCOPE__ .container:hover {
  transform: scale(1.1);
}

@keyframes like_effect {
  0% {
    transform: scale(0);
  }

  50% {
    transform: scale(1.2);
  }

  100% {
    transform: scale(1);
  }
}

@keyframes dislike_effect {
  0% {
    transform: scale(0);
  }

  50% {
    transform: scale(1.2);
  }

  100% {
    transform: scale(1);
  }
}
